Why is my average always a bit low?

```python
def average(scores):
    total = 0
    for i in range(1, len(scores)):
        total += scores[i]
    return total / len(scores)
```

reply:
It's the start of the `range`:

```python
for i in range(1, len(scores)):
```

Starting at `1` skips `scores[0]`, so the first score is never added but you still divide by the full count. Loop over the list directly:

```python
def average(scores):
    return sum(scores) / len(scores)
```

```tsx
import { useEffect, useState } from "react";

export function useFetch<T>(url: string) {
  const [data, setData] = useState<T | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    fetch(url)
      .then((res) => res.json())
      .then(setData)
      .catch(setError)
      .finally(() => setLoading(false));
  }, [url]);

  return { data, loading, error };
}
```

Then in a component: `const { data, loading } = useFetch<User[]>("/api/users");`

